import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Scanner;

public class Main {
    static Optional<Integer> firstBig(List<Integer> box, int t) {
        for (int x : box) {
            if (x >= t) {
                return Optional.of(x);
            }
        }
        return Optional.empty();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Integer> box = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            box.add(sc.nextInt());
        }
        Optional<Integer> found = firstBig(box, {t});
        System.out.println("柜子里有 " + box.size() + " 件");
        System.out.println("第一件够大的是：" + found.orElse(0));
    }
}
